import{_ as i,C as c,o as t,c as l,a2 as o,b as a,w as r,a as s,E as n,a3 as u}from"./chunks/framework.BaXgE4DV.js";const f=JSON.parse('{"title":"Circle","description":"","frontmatter":{},"headers":[],"relativePath":"features/circles.md","filePath":"features/circles.md","lastUpdated":1792234772000}'),C={name:"features/circles.md"};function g(p,e,h,q,E,A){const d=c("Mermaid");return t(),l("div",null,[e[1]||(e[1]=o('<h1 id="circle" tabindex="-1">Circle <a class="header-anchor" href="#circle" aria-label="Permalink to &quot;Circle&quot;">​</a></h1><p>Circle은 감사를 함께 나누는 소규모 비공개 그룹입니다. 공개 목록이나 검색은 없고 초대 코드로만 참여합니다. 사용자는 여러 Circle에 참여할 수 있습니다. 글은 기본이 &quot;나만 보기&quot;이고, 글을 쓸 때 &quot;Circle에 공유&quot;와 Circle을 직접 고른 경우에만 그 Circle에 보입니다. → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a></p><p>모임 리더를 위한 공개 안내 페이지는 <a href="https://grato.today/circle-guide" target="_blank" rel="noreferrer">grato.today/circle-guide</a>입니다(<code>SEO_PAGES[&#39;circle-guide&#39;]</code>, 미리 렌더링). → <a href="#guide-page">Circle 가이드 페이지</a></p><p>멤버십 변경(생성·참여·탈퇴·내보내기·삭제·초대 코드)은 <strong>모두 callable 함수</strong>가 처리합니다. 클라이언트는 그룹의 이름·설명·사진만 직접 고칠 수 있고, 그것도 관리자만 가능합니다. → <a href="/grato-docs/decisions#adr-3">결정 기록 #3</a></p><p>예외로, 운영자가 여는 Circle 하나 &quot;모두의 감사방&quot;은 초대 코드 없이 원하는 사람이 별명으로 참여합니다. 처음에는 꺼져 있습니다. → <a href="#open-circle">모두의 감사방</a></p><h2 id="한도" tabindex="-1">한도 <a class="header-anchor" href="#한도" aria-label="Permalink to &quot;한도&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th><th>확인 위치</th></tr></thead><tbody><tr><td>사용자당 참여 Circle</td><td>20개</td><td><code>createCircle</code>, <code>joinCircle</code></td></tr><tr><td>Circle당 멤버</td><td>50명 (모두의 감사방 999명)</td><td><code>joinCircle</code> (<code>joinOpenCircle</code>)</td></tr><tr><td>초대 코드 유효 기간</td><td>발급 후 30일</td><td><code>joinCircle</code></td></tr><tr><td>초대 코드 사용 횟수</td><td>50회</td><td><code>joinCircle</code></td></tr><tr><td>Circle 이름</td><td>1~30자</td><td>함수, 규칙(관리자 수정)</td></tr><tr><td>Circle 설명</td><td>100자 이하</td><td>함수, 규칙(관리자 수정)</td></tr><tr><td>Circle 사진</td><td>이미지, 5MB 미만, 관리자만</td><td>Storage 규칙</td></tr></tbody></table><p>Circle 수를 셀 때는 <code>users.groupIds</code>를 그대로 믿지 않고, 함수가 각 그룹 문서를 읽어 <strong>실제로 멤버인 Circle만</strong> 셉니다. 삭제된 Circle이나 내보내진 Circle의 ID가 남아 있어도 한도에 걸리지 않고, 그 자리에서 정리됩니다.</p><h2 id="역할" tabindex="-1">역할 <a class="header-anchor" href="#역할" aria-label="Permalink to &quot;역할&quot;">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>할 수 있는 일</th></tr></thead><tbody><tr><td>관리자 (<code>adminId</code>, 생성자)</td><td>이름·설명·사진 수정, 초대 코드 재발급, 멤버 내보내기·다시 허용, Circle 삭제. 탈퇴는 불가</td></tr><tr><td>멤버</td><td>글 읽기·쓰기, 리액션, 댓글, 탈퇴</td></tr></tbody></table><p>관리자 위임 기능은 아직 없습니다. 다만 관리자가 <a href="/grato-docs/features/account#deletion-scope">계정을 삭제</a>하면 가장 오래 함께한 멤버(<code>memberIds</code>의 참여 순서)가 자동으로 관리자가 되고, 혼자였다면 Circle이 삭제됩니다.</p><p>멤버는 Circle 설정의 멤버 목록에서 다른 멤버를 신고·차단할 수 있고, 관리자가 아닌 멤버는 &quot;Circle 신고하기&quot;로 Circle 자체를 신고할 수 있습니다. 차단은 내 화면만 바꾸고 멤버십은 그대로입니다. → <a href="/grato-docs/features/safety">신고·차단</a></p><h2 id="생성" tabindex="-1">생성 <a class="header-anchor" href="#생성" aria-label="Permalink to &quot;생성&quot;">​</a></h2><p><code>createCircle({name, description})</code> → <code>{groupId, inviteCode}</code></p><p>한 트랜잭션에서 그룹 문서(<code>memberIds: [나]</code>, <code>adminId: 나</code>, <code>plan: &quot;free&quot;</code>), 초대 코드 문서, 내 <code>groupIds</code>를 함께 만듭니다. 초대 코드가 이미 쓰이고 있으면 최대 5번까지 다시 뽑습니다. 이름·설명에 욕설·혐오 표현이 있으면 &quot;Circle 이름이나 설명에 쓸 수 없는 표현이 있어요&quot;로 거절합니다.</p><h2 id="초대-코드" tabindex="-1">초대 코드 <a class="header-anchor" href="#초대-코드" aria-label="Permalink to &quot;초대 코드&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>새 코드</th><th>예전 코드</th></tr></thead><tbody><tr><td>형식</td><td>8자리, <code>ABCDEFGHJKLMNPQRSTUVWXYZ23456789</code> (헷갈리는 <code>0 O 1 I</code> 제외)</td><td>대부분 6자리 영숫자</td></tr><tr><td>생성</td><td><code>crypto.randomInt</code> (암호학적 난수, 편향 없음)</td><td>-</td></tr><tr><td>만료·사용 횟수</td><td>30일, 50회</td><td>필드가 없으면 무제한</td></tr></tbody></table><ul><li>입력은 앞뒤 공백 제거 후 대문자로 바꿉니다(<code>normalizeInviteCode</code>). 영숫자 1~16자가 아니면 &quot;초대 코드를 찾을 수 없어요&quot;입니다.</li><li>초대 링크는 <code>https://grato.today/invite/{코드}</code> 형식입니다. 링크 미리보기(Circle 이름, 인원)는 <code>shareRenderer</code>가 만듭니다.</li><li>클라이언트는 아는 코드 하나만 조회할 수 있고 코드 목록은 볼 수 없습니다.</li></ul><h2 id="join" tabindex="-1">참여 <a class="header-anchor" href="#join" aria-label="Permalink to &quot;참여 {#join}&quot;">​</a></h2>',19)),(t(),a(u,null,{default:r(()=>[n(d,{id:"mermaid-236",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20U%20as%20%EC%82%AC%EC%9A%A9%EC%9E%90%0A%20%20participant%20C%20as%20%ED%81%B4%EB%9D%BC%EC%9D%B4%EC%96%B8%ED%8A%B8%0A%20%20participant%20J%20as%20joinCircle%0A%20%20participant%20F%20as%20Firestore%0A%20%20U-%3E%3EC%3A%20%EC%B4%88%EB%8C%80%20%EB%A7%81%ED%81%AC%20%EC%97%B4%EA%B8%B0%20%EB%98%90%EB%8A%94%20%EC%BD%94%EB%93%9C%20%EC%9E%85%EB%A0%A5%0A%20%20Note%20over%20C%3A%20%EB%B9%84%EB%A1%9C%EA%B7%B8%EC%9D%B8%EC%9D%B4%EB%A9%B4%20pendingInviteCode%20%EC%A0%80%EC%9E%A5%20%ED%9B%84%20%EB%A1%9C%EA%B7%B8%EC%9D%B8%0A%20%20C-%3E%3EC%3A%20profileReady%20%EB%8C%80%EA%B8%B0%20(users%20%EB%AC%B8%EC%84%9C%20%EB%A8%BC%EC%A0%80%20%EC%83%9D%EC%84%B1)%0A%20%20C-%3E%3EJ%3A%20joinCircle(%7Bcode%7D)%0A%20%20J-%3E%3EF%3A%20%ED%8A%B8%EB%9E%9C%EC%9E%AD%EC%85%98%20%EC%8B%9C%EC%9E%91%20%C2%B7%20inviteCodes%2F%7Bcode%7D%20%EC%9D%BD%EA%B8%B0%0A%20%20J-%3E%3EF%3A%20groups%2F%7BgroupId%7D%20%C2%B7%20users%2F%7Buid%7D%20%EC%9D%BD%EA%B8%B0%0A%20%20alt%20%EC%9D%B4%EB%AF%B8%20%EB%A9%A4%EB%B2%84%0A%20%20%20%20J-%3E%3EF%3A%20%ED%95%84%EC%9A%94%ED%95%98%EB%A9%B4%20groupIds%20%EB%B3%B5%EA%B5%AC%0A%20%20%20%20J--%3E%3EC%3A%20alreadyMember%20%3D%20true%0A%20%20else%20%EC%83%88%20%EC%B0%B8%EC%97%AC%0A%20%20%20%20Note%20over%20J%3A%20%EC%B0%A8%EB%8B%A8%20%EB%AA%A9%EB%A1%9D%20%C2%B7%20%EB%A7%8C%EB%A3%8C%20%C2%B7%20%EC%82%AC%EC%9A%A9%20%ED%9A%9F%EC%88%98%20%C2%B7%20%EC%A0%95%EC%9B%90%20%C2%B7%20Circle%20%EC%88%98%20%ED%99%95%EC%9D%B8%0A%20%20%20%20J-%3E%3EF%3A%20memberIds%20%2B%3D%20uid%0A%20%20%20%20J-%3E%3EF%3A%20groupIds%20%EA%B0%B1%EC%8B%A0%20(%EC%98%A4%EB%9E%98%EB%90%9C%20ID%20%EC%A0%95%EB%A6%AC)%0A%20%20%20%20J-%3E%3EF%3A%20useCount%20%2B%3D%201%0A%20%20%20%20J--%3E%3EC%3A%20alreadyMember%20%3D%20false%0A%20%20end%0A%20%20C-%3E%3EC%3A%20%ED%95%B4%EB%8B%B9%20Circle%EC%9D%84%20%EC%84%A0%ED%83%9D%ED%95%98%EA%B3%A0%20%ED%99%88%EC%9C%BC%EB%A1%9C%20%EC%9D%B4%EB%8F%99%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<ul><li>이미 멤버면 오류가 아니라 <code>alreadyMember: true</code>이고 사용 횟수를 차감하지 않습니다.</li><li>검사 순서: 코드 존재 → Circle 존재 → 이미 멤버 → <strong>내보낸 사용자</strong> → 만료 → 사용 횟수 → 정원 → 내 Circle 수.</li><li>신규 사용자는 클라이언트가 <code>users/{uid}</code>를 먼저 만들도록 <code>profileReady</code>를 기다린 뒤 참여합니다.</li><li>인앱 브라우저(카카오톡 등)에서는 Google 로그인이 막힙니다. <strong>카카오톡·LINE</strong>에서 초대 링크를 열면 초대 페이지가 한 번 자동으로 휴대폰 브라우저에 넘깁니다(카카오톡 <code>kakaotalk://web/openExternal</code>, LINE <code>openExternalBrowser=1</code>). 앱이 설치된 휴대폰이면 이때 Universal Link·App Link로 <strong>앱의 초대 화면</strong>이 열립니다. 넘기지 못하면(다른 인앱 브라우저, 세션당 한 번 시도 뒤) 브라우저 열기·링크 복사 안내를 보여 줍니다. <code>src/lib/inAppBrowser.js</code>의 <code>externalBrowserUrl</code>.</li><li>초대 메시지(<code>inviteMessage</code>)에는 링크와 함께 초대 코드가 들어 있어, 앱에서 &quot;Circle 참여하기&quot;에 코드를 넣어도 됩니다.</li><li>Circle을 만들면 바로 &quot;초대하기&quot; 카드(공유 시트, 카카오톡 포함)가 나옵니다. 혼자인 Circle은 쓰이지 않아서입니다.</li></ul><p>오류 메시지 전체는 <a href="/grato-docs/architecture/cloud-functions#circle-errors">Cloud Functions</a>에 있습니다.</p><h2 id="order" tabindex="-1">순서 바꾸기 <a class="header-anchor" href="#order" aria-label="Permalink to &quot;순서 바꾸기 {#order}&quot;">​</a></h2><p>Circle 탭 &quot;내 Circle&quot; 목록 위의 <strong>[순서 바꾸기]</strong> → 각 Circle에 ↑·↓ 버튼이 나오고, 누를 때마다 바로 저장됩니다(<code>users.circleOrder</code>). <strong>[완료]</strong> 로 닫습니다. Circle이 2개 이상일 때만 보입니다.</p><ul><li>홈의 Circle 탭(내 기록 다음), Circle 목록, 쓰기 화면의 Circle 선택이 모두 이 순서입니다. 홈 &quot;오늘 Circle 활동&quot;도 앞쪽 Circle부터 셉니다.</li><li>순서를 정한 뒤 새로 참여한 Circle은 맨 뒤에 붙고, 나간 Circle은 순서에서 무시됩니다.</li><li>내 기기에만이 아니라 계정에 저장되어 다른 기기에서도 같은 순서입니다. 다른 멤버에게는 영향이 없습니다.</li><li>정렬은 순수 함수 <code>src/lib/circleOrder.js</code>(<code>orderCircles</code>, <code>moveCircle</code>)가 하고 <code>groupStore</code>가 목록을 이 순서로 둡니다.</li></ul><h2 id="leave" tabindex="-1">나가기 <a class="header-anchor" href="#leave" aria-label="Permalink to &quot;나가기 {#leave}&quot;">​</a></h2><p><code>leaveCircle({groupId})</code> — 내 uid를 <code>memberIds</code>에서, Circle을 내 <code>groupIds</code>에서 뺍니다. 관리자는 나갈 수 없습니다(먼저 Circle을 삭제해야 함).</p><p>화면은 Circle 설정 맨 아래 <strong>&quot;주의해 주세요&quot;</strong> 카드의 <strong>[Circle 나가기]</strong> → 확인 창(&quot;Circle에서 나갈까요?&quot;, 버튼 &quot;나가기&quot;)입니다. 같은 카드에 관리자는 [Circle 삭제], 멤버는 [Circle 신고하기]가 있습니다(모두의 감사방은 신고 버튼 없음).</p><p>Circle이 이미 없거나 내가 멤버가 아니면 <code>groupIds</code>만 정리하고 성공합니다. 클라이언트는 이것을 이용해 삭제가 확인된 Circle의 오래된 ID를 서버에서도 지웁니다.</p><h2 id="멤버-내보내기와-다시-허용" tabindex="-1">멤버 내보내기와 다시 허용 <a class="header-anchor" href="#멤버-내보내기와-다시-허용" aria-label="Permalink to &quot;멤버 내보내기와 다시 허용&quot;">​</a></h2><table tabindex="0"><thead><tr><th>함수</th><th>동작</th></tr></thead><tbody><tr><td><code>removeCircleMember({groupId, memberId})</code></td><td><code>memberIds</code>에서 제거, <code>removedIds</code>에 추가, 그 사람의 <code>groupIds</code>에서 제거</td></tr><tr><td><code>unbanCircleMember({groupId, memberId})</code></td><td><code>removedIds</code>에서 제거</td></tr></tbody></table><ul><li>내보낸 사람은 이미 알고 있는 초대 코드로 <strong>다시 들어올 수 없습니다.</strong> &quot;이 Circle에서 내보내져 다시 참여할 수 없어요. Circle 관리자에게 문의해주세요&quot; 오류를 받습니다.</li><li>관리자는 Circle 설정의 &quot;내보낸 멤버&quot; 목록에서 <strong>다시 허용</strong>할 수 있습니다. 다시 허용해도 자동으로 멤버가 되지는 않고, 초대 코드로 다시 참여해야 합니다.</li><li>초대 코드를 바꾸지 않아도 차단이 유지되므로, 한 사람을 내보내려고 모든 멤버에게 새 코드를 나눠 줄 필요가 없습니다.</li><li>내보내진 사람이 그 Circle에 쓴 글은 작성자 본인에게 계속 보입니다. 그 사람은 더 이상 Circle 피드를 읽거나 새 글을 올릴 수 없습니다.</li></ul><h2 id="circle-삭제" tabindex="-1">Circle 삭제 <a class="header-anchor" href="#circle-삭제" aria-label="Permalink to &quot;Circle 삭제&quot;">​</a></h2><p><code>deleteCircle({groupId})</code> — 관리자만 가능합니다. 모두의 감사방은 거부합니다(<a href="#open-circle">위</a>).</p><ol><li>모든 멤버의 <code>users.groupIds</code>에서 이 Circle 제거 (없는 사용자 문서는 건너뜀)</li><li>이 Circle을 가리키는 초대 코드 전부 삭제, 첫 나눔 표시(<code>circleFirstShares</code>, <a href="/grato-docs/features/notifications#first-share">첫 나눔 알림</a>) 삭제</li><li>그룹 문서 삭제 (<strong>마지막</strong>)</li><li>Circle 사진(<code>circlePhotos/{groupId}/</code>) 삭제 (실패해도 로그만)</li></ol><p>운영자가 신고된 Circle을 지울 때(<code>moderate</code>)도 같은 처리를 씁니다. 500개 단위 배치로 나눠 커밋합니다. 그룹 문서를 마지막에 지우므로 중간에 실패해도 다시 호출하면 이어서 정리됩니다.</p><p><strong>감사 글은 지우지 않습니다.</strong> 그룹 문서가 사라지면 다른 멤버는 그 글을 읽을 수 없게 되지만, 작성자는 자기 글을 개인 기록으로 계속 봅니다. → <a href="/grato-docs/decisions#adr-4">결정 기록 #4</a></p><h2 id="초대-코드-재발급" tabindex="-1">초대 코드 재발급 <a class="header-anchor" href="#초대-코드-재발급" aria-label="Permalink to &quot;초대 코드 재발급&quot;">​</a></h2><p><code>regenerateInviteCode({groupId})</code> → <code>{inviteCode}</code> — 관리자만. 기존 코드 문서를 <strong>모두</strong> 지우고 새 코드를 만든 뒤 <code>groups.inviteCode</code>를 바꿉니다. 한 트랜잭션이라 중간 상태가 없습니다. 기존 링크·코드는 즉시 쓸 수 없게 됩니다.</p><h2 id="circle-정보-수정" tabindex="-1">Circle 정보 수정 <a class="header-anchor" href="#circle-정보-수정" aria-label="Permalink to &quot;Circle 정보 수정&quot;">​</a></h2><p>관리자는 Firestore에 직접 <code>name</code>(1~30자), <code>description</code>(100자 이하), <code>photoURL</code>만 수정할 수 있습니다. 이름·설명을 바꾸면 서버가 내용 필터로 검사해, 걸리면 그대로 두고 운영자에게 알립니다(<code>onCircleNameWritten</code>). 사진은 Storage <code>circlePhotos/{groupId}/</code>에 올리며, Storage 규칙이 Firestore의 <code>adminId</code>를 교차 확인합니다. → <a href="/grato-docs/architecture/security-rules#storage">보안 규칙</a></p><h2 id="피드" tabindex="-1">피드 <a class="header-anchor" href="#피드" aria-label="Permalink to &quot;피드&quot;">​</a></h2><ul><li>Circle별로 최신 20개를 실시간 구독하고, &quot;더 보기&quot;는 커서(<code>startAfter</code>) 기반으로 20개씩 읽습니다.</li><li>여러 Circle을 한 번에 합친 피드는 지원하지 않습니다. 규칙의 교차 읽기 한도 때문에 Circle마다 쿼리를 따로 보냅니다. → <a href="/grato-docs/architecture/security-rules#get-list">보안 규칙</a></li><li>홈의 &quot;오늘의 Circle 활동&quot;은 최대 10개 Circle에 대해 오늘(KST) 글 수와 리액션 수를 병렬로 집계합니다.</li><li>구독 중 권한이 사라지면(내보내짐 등) 빈 피드로 처리해 로딩이 끝나지 않는 일을 막습니다.</li></ul><h2 id="first-share" tabindex="-1">첫 나눔 <a class="header-anchor" href="#first-share" aria-label="Permalink to &quot;첫 나눔 {#first-share}&quot;">​</a></h2><p>한 사람이 그 Circle에 처음 나눈 글은 혼자 남지 않게 조금 다르게 보입니다(GRATO-51). 판정은 서버가 합니다 → <a href="/grato-docs/features/notifications#first-share">첫 나눔 알림</a>.</p><ul><li><strong>멤버 알림</strong>: 새 글 알림이 &quot;{이름}님이 Circle에 처음 감사를 나눴어요 🌱&quot;로 바뀜(알림 수는 같음). 24시간 동안 반응이 없으면 리더에게 한 번 → <a href="/grato-docs/features/notifications#first-share-followup">리더 알림</a></li><li><strong>피드 카드 표시</strong>: Circle 피드에서 그 글의 작성자 이름 아래에 작은 표시 <strong>&quot;처음 나눈 감사&quot;</strong>(새싹 아이콘)가 만든 지 7일 동안 붙습니다. 서버가 쓰는 <code>gratitudes.firstShare</code>를 보고 그립니다(클라이언트는 쓸 수 없음, 규칙 테스트). 내 기록·저장한 감사에는 붙이지 않습니다. 계산은 <code>src/lib/firstShare.js</code>(<code>showsFirstShareBadge</code>, 테스트)</li><li><strong>저장 직후 안내</strong>: Circle에 저장한 뒤 그 Circle 피드 위에 **&quot;Circle 멤버에게 알렸어요&quot;**가 5초 보입니다. 이 기기에 이미 읽어 둔 그 Circle 피드에 내 글이 하나도 없을 때만(추가 요청 없이 추측, ADR-13). 틀려도 해가 없습니다: 멤버는 Circle 글마다 알림을 받습니다. 몇 명에게 갔는지는 쓰지 않습니다</li><li>쓰는 사람에게 반응 수·읽음·&quot;아직&quot; 같은 상태는 어디에도 보이지 않습니다</li><li><strong>모두의 감사방</strong>: 표시도 안내도 없습니다(새 글 알림이 없는 방)</li><li>웹은 Hosting 배포로, 앱은 **iOS 1.0.1 (5)**부터. 예전 앱은 <code>firstShare</code>를 무시해 그대로 동작합니다</li></ul><h2 id="open-circle" tabindex="-1">모두의 감사방 (별명 Circle) <a class="header-anchor" href="#open-circle" aria-label="Permalink to &quot;모두의 감사방 (별명 Circle) {#open-circle}&quot;">​</a></h2><p>운영자가 여는 Circle 하나로, 누구나 원하면 별명을 정해 참여합니다(자동 참여는 없음). <strong>기능은 꺼진 채로 배포되고</strong>, 운영자가 <a href="/grato-docs/operations/deploy#open-circle">켜기 절차</a>를 마친 뒤 켭니다. 꺼져 있는 동안에는 아무것도 보이지 않고 참여도 거부됩니다. → <a href="/grato-docs/decisions#adr-21">결정 기록 #21</a>, <a href="/grato-docs/architecture/data-model#open-circle">데이터 모델</a></p><table tabindex="0"><thead><tr><th>항목</th><th>모두의 감사방</th><th>일반 Circle</th></tr></thead><tbody><tr><td>참여</td><td>초대 코드 없이, 별명을 정해 (<code>joinOpenCircle</code>)</td><td>초대 코드</td></tr><tr><td>정원</td><td>999명 (<code>maxMembers</code>)</td><td>50명</td></tr><tr><td>글·댓글의 작성자</td><td>이 방의 별명, 사진 없음(첫 글자 아바타)</td><td>공개 이름과 프로필 사진</td></tr><tr><td>멤버 목록</td><td>보여 주지 않음(&quot;멤버 N명&quot;만)</td><td>Circle 설정에 표시</td></tr><tr><td>새 글 알림</td><td>없음</td><td>멤버에게</td></tr><tr><td>공감 알림</td><td>공감한 사람의 별명(없으면 &quot;누군가 공감했어요&quot;)</td><td>공개 이름</td></tr><tr><td>관리자</td><td>운영 전용 계정(&quot;Grato 운영팀&quot;)</td><td>만든 사람</td></tr><tr><td>삭제</td><td>앱에서 불가, 운영자가 설정 스크립트(<code>--delete</code>)로</td><td>관리자</td></tr></tbody></table><p><strong>참여 화면.</strong> 기능이 켜져 있고 아직 참여하지 않았으면 Circle 탭의 &quot;내 Circle&quot; 위에 방 이름·설명과 <strong>[별명 정하고 참여]</strong> 카드가 보입니다. 이름·설명은 <code>appConfig/openCircle</code>의 사본입니다(멤버가 아니면 그룹 문서와 멤버 목록을 읽을 수 없음, 관리자가 이름을 바꾸면 운영자가 <code>--sync</code>). 누르면 아래 시트가 열립니다.</p><ul><li>안내: &quot;이 방에서는 내 이름 대신 별명만 보여요.&quot; / &quot;신고 처리를 위해 운영자는 작성자를 확인할 수 있어요.&quot; / &quot;불쾌한 콘텐츠와 괴롭힘은 무관용 원칙으로 금지해요.&quot; / 글은 지금처럼 기본이 나만 보기</li><li>&quot;이 방에서 쓸 별명&quot; 입력(2~12자). 서버가 거절하면 그 이유(&quot;이미 쓰는 별명이에요&quot;, &quot;운영자로 오해할 수 있는 별명은 쓸 수 없어요&quot;, &quot;인원이 가득 찼어요&quot; 등)를 보여 줍니다. → <a href="/grato-docs/architecture/cloud-functions#join-open-circle">오류 메시지</a></li><li><strong>[별명으로 참여하기]</strong> → 참여하면 Circle 탭에 그대로 머물며 &quot;…에 참여했어요&quot; 안내가 보이고, 내 Circle 목록에 이 방이 들어옵니다. 홈을 열면 이 방의 피드 탭이 선택되어 있습니다(초대 코드로 참여할 때와 같음).</li><li>전각 문자는 반각으로 저장됩니다(&quot;ＨＡ&quot; → &quot;HA&quot;).</li><li>별명은 참여한 뒤에도 Circle 설정에서 바꿀 수 있습니다(아래).</li></ul><p><strong>참여한 뒤.</strong> 다른 Circle처럼 내 Circle 목록과 홈 탭, 쓰기 화면의 Circle 선택에 나오고, 목록에는 &quot;별명: 햇살가득&quot;이 붙습니다. 쓰기 화면에서 이 방을 고르면 &quot;별명 &#39;햇살가득&#39;(으)로 올라가요&quot;가 보입니다. 이 방 글에 다는 댓글도 별명으로 올라갑니다. 홈 &quot;오늘 Circle 활동&quot;에도 들어갑니다.</p><p><strong>Circle 설정.</strong> 초대 코드와 멤버 목록 대신 &quot;이 방에서 쓰는 별명&quot;과 짧은 태그(이름·사진 대신 별명 / 누구나 참여 / 멤버 목록 비공개 / 별명은 7일에 한 번 변경)가 보입니다. 운영자가 작성자를 확인할 수 있다는 안내는 참여 시트에 있습니다.</p><p><strong>별명 바꾸기.</strong> 별명 오른쪽의 <strong>[바꾸기]</strong> → 시트에 지금 별명이 채워져 있고, 새 별명을 넣고 <strong>[별명 바꾸기]</strong>(지금 별명과 같으면 꺼짐). 규칙은 참여할 때와 같고(겹치지 않음, 금지어, 2~12자), <strong>7일에 한 번</strong> 바꿀 수 있습니다(참여한 뒤 첫 변경은 바로). 너무 이르면 &quot;별명은 7일에 한 번 바꿀 수 있어요. 10월 23일 14:05부터 바꿀 수 있어요&quot;처럼 언제부터인지 보여 줍니다. 바꾸면 &quot;별명을 바꿨어요. 이 방에 쓴 글과 댓글에도 곧 반영돼요.&quot; — 이번 참여 뒤 이 방에 쓴 글·댓글이 몇 초 안에 새 별명으로 바뀝니다(예전 참여 때 쓴 글은 그때 별명 그대로). 예전 별명은 바로 다른 사람이 쓸 수 있습니다. 차단 목록에는 차단할 때의 별명이 남습니다. → <a href="/grato-docs/architecture/cloud-functions#rename-open-circle-alias"><code>renameOpenCircleAlias</code></a> 방 자체는 운영자가 운영해 <strong>[Circle 신고하기]가 없습니다</strong>(글·댓글·사람 신고는 평소처럼). 나가기는 다른 Circle과 같고, 나가면 별명이 지워져 다른 사람이 쓸 수 있습니다(다시 참여할 때 새로 정함). 관리자(운영 계정)는 이름·설명·사진을 다른 Circle처럼 고치고(이름·설명을 바꾸면 운영자가 <code>setupOpenCircle --sync</code>로 참여 카드에 반영), &quot;Circle 삭제&quot; 버튼은 없습니다.</p><p><strong>별명은 가명입니다.</strong> 글에는 <code>userId</code>가 그대로 있어 규칙·삭제·통계·신고가 평소처럼 동작하고, 운영자는 신고된 글의 작성자를 운영자 화면에서 확인합니다. 앱은 이 방에서 작성자의 실제 프로필을 찾아 보여 주지 않습니다(멤버 목록 없음, 차단 목록은 별명으로 표시).</p><p><strong>신고·차단.</strong> 신고는 평소와 같습니다. 별명 글·댓글에서 차단하면 차단 문서에 별명이 함께 저장되고, 차단한 사용자 화면에 &quot;햇살가득 · 모두의 감사방 별명&quot;으로 보입니다. 차단은 사람(uid) 단위라 그 사람의 다른 Circle 글도 함께 가려집니다.</p><p><strong>계정 삭제와 정리.</strong> 탈퇴·내보내기·계정 삭제 때 별명과 선점이 함께 지워집니다. 내보낸 사람은 다시 참여할 수 없습니다. 운영 계정을 삭제해도 방은 멤버에게 넘어가거나 지워지지 않고 관리자 없이 남으며, 운영자가 설정 스크립트로 새 관리자를 정합니다.</p><p><strong>방 삭제.</strong> 앱에서는 지울 수 없습니다. <code>deleteCircle</code>(관리자)과 <code>moderate</code>의 Circle 삭제(운영자)가 &quot;모두의 감사방은 운영자가 관리해서 앱에서 삭제할 수 없어요&quot;로 거부합니다. 지우려면 운영자가 <code>setupOpenCircle --delete</code>를 실행합니다(다른 Circle 삭제와 같은 정리 + 모든 별명·선점 + <code>appConfig/openCircle</code>, 글은 개인 기록으로 남음). → <a href="/grato-docs/architecture/cloud-functions#setup-open-circle">스크립트</a></p><h3 id="daily-topic" tabindex="-1">오늘의 주제 <a class="header-anchor" href="#daily-topic" aria-label="Permalink to &quot;오늘의 주제 {#daily-topic}&quot;">​</a></h3><p>모두의 감사방 맨 위에 매일 <strong>07:00(KST)</strong> 주제 하나가 올라갑니다(Reddit의 daily thread처럼). 답은 댓글이 아니라 <strong>감사 글</strong>로 저장되어 기록한 날·감사 수·배지·연속일에 그대로 쌓이고, 방에서는 주제 아래에 모여 보입니다. 운영 규칙(요일별 결, 문구 규칙, 4주 초안, 운영자 체크리스트)은 내부 운영 안(GRATO-3)을 따릅니다. → <a href="/grato-docs/decisions#adr-31">결정 기록 #31</a>, <a href="/grato-docs/architecture/data-model#daily-topics">데이터 모델</a></p><p><strong>주제 카드</strong> (홈 › 모두의 감사방 탭, 피드 위)</p><ul><li>&quot;오늘의 주제 · 월 · 작은 일상&quot;과 주제 문구. 선정된 사용자 질문이면 &quot;💡 Grato 사용자가 제안한 질문&quot; — 이 방에서는 제안자의 실제 이름을 보이지 않습니다.</li><li>숫자는 <strong>&quot;오늘 n명이 답했어요&quot; 하나</strong>뿐입니다. 이 방에 나눈 답의 사람 수이고, 숨김 글과 내가 차단한 사람은 빼고 셉니다. 3명 미만이면 숫자 대신 &quot;첫 답을 남겨 보세요&quot;(내가 답했으면 &quot;답을 남겼어요. 다른 답을 기다리고 있어요&quot;).</li><li><strong>[답하기]</strong> → 쓰기 화면. <strong>&quot;오늘 주제 말고 자유롭게 써도 돼요&quot;</strong> → 보통 쓰기 화면. 답하지 않아도 되고, 답하지 않은 날을 따로 표시하거나 알리지 않습니다.</li><li>주제의 하루는 07:00부터 다음 날 06:59까지입니다. 그 사이에 쓴 답은 같은 주제의 답이고, 기록한 날은 지금처럼 쓴 KST 날짜로 셉니다. 그날 주제가 없으면 카드가 보이지 않습니다.</li></ul><p><strong>답 목록</strong> (카드 아래, &quot;오늘의 답 · 새 답이 위에 있어요&quot;)</p><ul><li><strong>시간순, 새 답이 위.</strong> 인기순·공감순·베스트 답·운영자 추천 고정은 없습니다.</li><li><strong>내가 답하기 전에는 새 답 3개만</strong> 보이고 &quot;답하면 오늘의 답을 모두 볼 수 있어요&quot;가 나옵니다. <strong>나만 보기로 답해도</strong> 전부 열립니다. 이 잠금은 쓰게 하려는 안내일 뿐 보안 장치가 아닙니다(멤버는 원래 이 방의 글을 모두 읽을 수 있음).</li><li>다 열린 뒤에는 10개씩 &quot;답 더 보기&quot;. 카드는 답을 최근 200개까지 읽습니다(그보다 많으면 &quot;n명 넘게&quot;).</li><li>답에도 공감·댓글·저장·신고·차단은 다른 글과 같습니다. 다만 <strong>답의 공감 숫자는 작성자 본인에게만</strong> 보입니다(다른 사람에게는 이모지만). 운영자는 신고 확인 화면에서 숫자를 봅니다.</li><li>오늘 주제의 답은 피드에서 빠지고 카드 아래에만 나옵니다. 지난 주제의 답은 피드에 보통 글처럼, 글 위에 작게 &quot;오늘의 주제: …&quot;를 달고 보입니다.</li></ul><p><strong>답 쓰기</strong> (<code>/write?topic=YYYY-MM-DD</code>)</p><ul><li>맨 위에 &quot;오늘의 주제에 답하기&quot;와 주제 문구, X(주제 없이 쓰기). &quot;질문으로 쓰기&quot; 안내는 숨깁니다.</li><li><strong>제목은 쓰지 않아도 됩니다</strong>(한 줄 답도 됨). 내용은 다른 글과 같은 기준입니다.</li><li>공개 범위는 지금처럼 <strong>나만 보기가 기본이고 이 방을 미리 고르지 않습니다.</strong> 고를 수 있는 Circle은 모두의 감사방뿐입니다(다른 Circle에는 답을 올릴 수 없음). 이 방을 고르면 버튼이 &quot;이 방에 나누기&quot;, 별명으로 올라갑니다.</li><li>저장하면 이 방 탭으로 돌아가 답 목록이 열립니다. 내 기록의 그 글 위에도 &quot;오늘의 주제: …&quot;가 보입니다.</li><li>운영자가 문구를 막 고쳐 저장이 거부되면 주제를 다시 읽어 한 번 더 저장합니다.</li></ul><p><strong>운영자 화면</strong> (관리자 › <strong>주제</strong>)</p><ul><li>날짜(오늘의 주제 날부터 92일 뒤까지), 출처(운영자 / 선정 질문 / 시즌), 문구, 결(요일 기본값)을 고르고 <strong>[주제 예약하기]</strong>. 하루에 하나입니다.</li><li>서버가 막는 것: 5~80자 밖, 링크·연락처·욕설, &quot;AI&quot;·&quot;인공지능&quot;, 앞뒤 8주 안의 같은 문구. 화면은 권장(질문 하나, 15–50자, 물음표)을 안내합니다.</li><li>선정 질문은 질문 탭에서 선정한 사용자 질문(첫 질문) 중에서 고릅니다. 시즌 주제는 <code>seasonKey</code>(예: <code>2026-thanks</code>, 배지·시즌 질문과 같은 형식)를 붙입니다(GRATO-66).</li><li>올라간 주제는 문구를 고칠 수 있고(그 뒤의 답부터 새 문구), 지울 수는 없습니다. 예약 중인 주제는 지울 수 있습니다.</li><li>쓰기는 모두 <code>manageDailyTopic</code> callable이고 <code>adminAuditLogs</code>에 남습니다. 운영 계정(&quot;Grato 운영팀&quot;)으로 답하거나 공감하지 않습니다. → <a href="/grato-docs/architecture/cloud-functions#manage-daily-topic">Cloud Functions</a></li></ul><p><strong>이용 기록</strong>: <code>topic_card_viewed</code>(주제마다 세션에 한 번, <code>answered</code>), <code>topic_unlock_prompt_viewed</code>, <code>topic_write_started</code>, <code>gratitude_created</code>의 <code>topicId</code>. 주제·답 문구는 넣지 않습니다.</p><h2 id="guide-page" tabindex="-1">Circle 가이드 페이지 <a class="header-anchor" href="#guide-page" aria-label="Permalink to &quot;Circle 가이드 페이지 {#guide-page}&quot;">​</a></h2><p><code>/circle-guide</code>는 교회 소그룹, 독서모임, 가족, 친구 모임의 리더를 위한 공개 페이지입니다. 본문과 자주 묻는 질문은 <code>src/content/seoPages.js</code>(<code>SEO_PAGES[&#39;circle-guide&#39;]</code>, <code>CIRCLE_GUIDE_FAQ</code>), 화면은 <code>src/pages/CircleGuidePage.jsx</code>입니다.</p><ul><li>이 문서의 한도(50명, 20개, 초대 코드 30일·50회), 탈퇴·내보내기·삭제 동작, 관리자 위임이 없다는 점을 그대로 씁니다. <strong>이 동작을 바꾸면 페이지 문구도 같이 고칩니다.</strong></li><li>시작 버튼: 웹에서 로그인하지 않았으면 &quot;웹에서 시작하기&quot;(<code>/login</code>)와 App Store 배지(<code>AppDownload</code>, 웹에서만), 로그인했거나 앱 안이면 &quot;Circle 만들러 가기&quot;(<code>/group</code>).</li><li>앱에서도 열리는 페이지라 본문에 다른 플랫폼 이름을 쓰지 않습니다(App Store 심사 가이드라인 2.3.10). <code>seoPages.test.js</code>가 확인합니다.</li><li>Circle이 하나도 없으면 Circle 탭의 빈 화면에 &quot;모임에서 Circle 쓰는 법 보기&quot; 링크가 있습니다.</li></ul>',52))])}const b=i(C,[["render",g]]);export{f as __pageData,b as default};
